export const priceLabel=(price?:string|null)=>price?Number(price).toLocaleString('fr-FR',{style:'currency',currency:'EUR'}):''

export function durationLabel(minutes:number){
  if(!(minutes>0))return ''
  const h=Math.floor(minutes/60),m=minutes%60
  return [h&&h+' h',m&&m+' min'].filter(Boolean).join(' ')
}

const slug=(text:string)=>text.replace(/œ/gi,'oe').replace(/æ/gi,'ae').normalize('NFD').replace(/\p{M}/gu,'').replace(/[^A-Za-z0-9]+/g,'-').replace(/^-+|-+$/g,'')

/** Preview of the reference generated by the API on save (Formation::refreshReference). */
export function referenceLabel(acronym:string,title:string,audience?:{name:string;acronym?:string}){
  const prefix=slug(audience?.acronym??'').toUpperCase()||(audience?.name.match(/\p{L}/u)?.[0].toUpperCase()??'')
  const own=slug(acronym).toUpperCase()||slug(title).toLowerCase()
  return prefix&&own?prefix+'-'+own:''
}
